
from datetime import date, timedelta
from pathlib import Path
import json
import math

from fastapi import APIRouter, HTTPException


# ============================================================
# STEP 20 - RESEARCH TFT FORECAST API
#
# Serves validated forecasts generated by Step 19.
#
# Does not retrain or execute the TFT.
# Does not write to MongoDB.
# Does not modify existing forecast endpoints.
# ============================================================

router = APIRouter(
    prefix="/forecast/research",
    tags=["Research TFT Forecasting"],
)

ROOT = Path(__file__).resolve().parents[2]

FORECAST_FILE = (
    ROOT
    / "research"
    / "outputs"
    / "tft_operational_forecasts"
    / "next_four_weeks_forecasts.json"
)

GRADES = ["BOP", "BOPF", "Dust", "OP", "Pekoe"]

FORECAST_HORIZON = 4
EXPECTED_FORECAST_COUNT = 20


def read_saved_forecast():
    if not FORECAST_FILE.is_file():
        raise HTTPException(
            status_code=503,
            detail=(
                "Research TFT forecast file is missing. "
                "Run Step 19 forecast generation first."
            ),
        )

    try:
        with FORECAST_FILE.open(
            "r",
            encoding="utf-8",
        ) as file:
            payload = json.load(
                file,
                parse_constant=lambda value: (
                    (_ for _ in ()).throw(
                        ValueError(
                            f"Invalid JSON constant: {value}"
                        )
                    )
                ),
            )

    except (OSError, ValueError, json.JSONDecodeError):
        raise HTTPException(
            status_code=503,
            detail=(
                "Saved research forecast data "
                "could not be read or parsed."
            ),
        )

    return payload


def validate_forecast_payload(payload):
    if not isinstance(payload, dict):
        raise ValueError(
            "Forecast payload must be an object."
        )

    if payload.get("status") != "PASS":
        raise ValueError(
            "Forecast generation status is not PASS."
        )

    if payload.get("model") != "no_price_tft":
        raise ValueError(
            "Unexpected forecasting model."
        )

    if payload.get("forecast_type") != (
        "dataset_origin_forecast"
    ):
        raise ValueError(
            "Unexpected forecast type."
        )

    try:
        origin = date.fromisoformat(
            payload["forecast_origin"]
        )
    except (KeyError, TypeError, ValueError) as error:
        raise ValueError(
            "Invalid forecast origin date."
        ) from error

    if payload.get("forecast_horizon_weeks") != (
        FORECAST_HORIZON
    ):
        raise ValueError(
            "Expected a four-week forecast horizon."
        )

    if payload.get("encoder_weeks") != 52:
        raise ValueError(
            "Unexpected historical encoder length."
        )

    if payload.get("target") != "demand_kg":
        raise ValueError(
            "Unexpected forecast target."
        )

    if payload.get("unit") != "kg":
        raise ValueError(
            "Unexpected forecast unit."
        )

    if payload.get("forecast_count") != (
        EXPECTED_FORECAST_COUNT
    ):
        raise ValueError(
            "Expected exactly 20 forecast records."
        )

    if payload.get("quantiles") != [0.1, 0.5, 0.9]:
        raise ValueError(
            "Unexpected forecast quantiles."
        )

    forecasts = payload.get("forecasts")

    if not isinstance(forecasts, dict):
        raise ValueError(
            "Forecasts must be grouped by tea grade."
        )

    if set(forecasts) != set(GRADES):
        raise ValueError(
            "Forecasts must contain all five tea grades."
        )

    total = 0
    normalized = {}

    for grade in GRADES:
        weekly = forecasts[grade]

        if not isinstance(weekly, list):
            raise ValueError(
                f"{grade}: forecasts must be a list."
            )

        if len(weekly) != FORECAST_HORIZON:
            raise ValueError(
                f"{grade}: expected four forecast weeks."
            )

        normalized_weeks = []

        for horizon, item in enumerate(
            weekly,
            start=1,
        ):
            if not isinstance(item, dict):
                raise ValueError(
                    f"{grade}: invalid forecast record."
                )

            try:
                actual_horizon = item["horizon"]
                week = date.fromisoformat(
                    item["week"]
                )

                lower = float(
                    item["lower_demand_kg"]
                )
                median = float(
                    item["median_demand_kg"]
                )
                upper = float(
                    item["upper_demand_kg"]
                )

            except (
                KeyError,
                TypeError,
                ValueError,
                OverflowError,
            ) as error:
                raise ValueError(
                    f"{grade}: invalid forecast values."
                ) from error

            expected_date = (
                origin + timedelta(weeks=horizon)
            )

            if (
                isinstance(actual_horizon, bool)
                or actual_horizon != horizon
            ):
                raise ValueError(
                    f"{grade}: incorrect forecast horizon."
                )

            if week != expected_date:
                raise ValueError(
                    f"{grade}: incorrect forecast date."
                )

            if not all(
                math.isfinite(value)
                for value in (lower, median, upper)
            ):
                raise ValueError(
                    f"{grade}: nonfinite forecast quantity."
                )

            if not (
                0 <= lower <= median <= upper
            ):
                raise ValueError(
                    f"{grade}: invalid demand interval."
                )

            normalized_weeks.append({
                "week": week.isoformat(),
                "horizon": horizon,
                "lower_demand_kg": round(lower, 2),
                "median_demand_kg": round(median, 2),
                "upper_demand_kg": round(upper, 2),
            })

            total += 1

        normalized[grade] = normalized_weeks

    if total != EXPECTED_FORECAST_COUNT:
        raise ValueError(
            "Unexpected total forecast record count."
        )

    return origin, normalized, total


@router.get("/latest")
def get_latest_research_forecast():
    """
    Return the latest saved research TFT forecasts.

    This is a dataset-origin forecast, not a
    live or continuously updated prediction.
    """
    payload = read_saved_forecast()

    try:
        origin, forecasts, count = (
            validate_forecast_payload(payload)
        )
    except ValueError:
        raise HTTPException(
            status_code=503,
            detail=(
                "Saved research forecast data failed "
                "integrity validation."
            ),
        )

    return {
        "status": "success",
        "model": "no_price_tft",
        "model_description": (
            "Selected Temporal Fusion Transformer "
            "without auction-price inputs"
        ),
        "forecast_type": "dataset_origin_forecast",
        "forecast_origin": origin.isoformat(),
        "forecast_horizon_weeks": FORECAST_HORIZON,
        "historical_input_weeks": 52,
        "tea_grade_count": len(GRADES),
        "forecast_count": count,
        "target": "demand_kg",
        "unit": "kg",
        "quantiles": {
            "lower": 0.1,
            "median": 0.5,
            "upper": 0.9,
        },
        "nominal_interval_coverage_percent": 80,
        "generated_at_utc": payload.get(
            "generated_at_utc"
        ),
        "forecasts": forecasts,
        "message": (
            "Saved four-week forecasts generated "
            "from historical factory data. "
            "These are not live predictions."
        ),
    }
